const ruTranslate = (value) => {
  let out = clean(value);
  for (const [from, to] of ruPairs.sort((a, b) => b[0].length - a[0].length)) {
    const escaped = from.replace(/[.*+?^${}()|[\]\\]/gu, '\\$&');
    const pattern = /^\p{L}+$/u.test(from) ? `(?<!\\p{L})${escaped}(?!\\p{L})` : escaped;
    out = out.replace(new RegExp(pattern, 'giu'), to);
  }
  return out.replace(/[іїєґ]/giu, (c) => ({ і: 'и', ї: 'и', є: 'е', ґ: 'г' }[c.toLocaleLowerCase('uk-UA')] ?? c)).replace(/\s{2,}/gu, ' ').trim();
};

