// Latest pricing rule from the user: retail only, delivery excluded, Prom
// commission fixed at 20%, target net profit at least 90% of purchase cost.
// The orienting price is cost * 1.90 / 0.80 and is rounded upward to a clean
// whole-hryvnia amount without inventing a wholesale offer.
const priceFor = (cost) => {
  const commission = 0.20; const expectedDelivery = 0; const worstDelivery = 0;
  const raw = (cost * 1.90) / (1 - commission); const final = Math.ceil(raw);
  const fee = final * commission; const expectedProfit = final - fee - cost;
  const worstProfit = expectedProfit; const target = cost * 0.90; const min = target;
  if (worstProfit + 1e-8 < min) throw new Error(`Price below target net profit: cost=${cost}, final=${final}, profit=${worstProfit}, target=${min}`);
  return { final, raw, commission, min, target, expectedDelivery, worstDelivery, expectedProfit, worstProfit };
};

